exact:
.days-nav{display:none}
.week{display:grid;gap:14px}
.day{padding:22px 20px;background:var(--surface);border-radius:18px}
.day h3{font-size:1.35rem;margin-bottom:10px}
.day ul{list-style:none;margin:0;padding:0}
.day li{display:grid;grid-template-columns:3.4rem 1fr;gap:10px;padding:10px 0;border-top:1px solid var(--line);font-size:.95rem;line-height:1.4}
.day time{font-weight:700;font-variant-numeric:tabular-nums}
.day li span small{display:block;color:var(--ink-2);font-size:.85rem}
.day.today{box-shadow:inset 0 0 0 2px var(--green)}
.day.today h3::after{content:"azi";margin-left:10px;font:600 .8rem var(--sans);color:var(--green);vertical-align:.2em}
.sched-note{margin:24px 0 0;color:var(--ink-2);font-size:.95rem;max-width:44rem}
@media (min-width:1000px){.week{grid-template-columns:repeat(6,minmax(0,1fr));gap:10px}.day{padding:20px 16px}.day li{grid-template-columns:1fr;gap:2px}}
@media (max-width:999px){
  .js .days-nav{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:6px;margin-bottom:12px}
  .days-nav button{min-height:46px;padding:0;border:1px solid transparent;border-radius:12px;background:var(--surface);color:var(--ink);font:600 .95rem var(--sans);cursor:pointer}
  .days-nav button[aria-pressed="true"]{background:var(--green);color:#fff}
  .js .day:not(.shown){display:none}
}

/* orar: ziua de azi e marcată; pe telefon se vede câte o zi, aleasă din butoane (duminica arată lunea) */
(function(){
  var today=new Date().getDay(),days=[].slice.call(document.querySelectorAll('.day')),btns=[].slice.call(document.querySelectorAll('.days-nav button'));
  days.forEach(function(d){if(+d.dataset.d===today)d.classList.add('today');});
  function show(n){
    days.forEach(function(d){d.classList.toggle('shown',d.dataset.d===n);});
    btns.forEach(function(b){b.setAttribute('aria-pressed',b.dataset.d===n?'true':'false');});
  }
  btns.forEach(function(b){b.addEventListener('click',function(){show(b.dataset.d);});});
  show(String(today===0?1:today));
})();
